/* Header submenus share the existing navigation labels, spacing and palette. */
.site-header{z-index:100}
#main-nav .nav-item{position:relative;align-self:stretch;display:flex;align-items:center}
#main-nav .nav-parent{display:block;padding-block:27px;white-space:nowrap}
#main-nav .nav-parent.active,#main-nav .nav-mobile-trigger.active{color:var(--green);box-shadow:inset 0 -3px var(--green)}
#main-nav>a.active{color:var(--green);box-shadow:inset 0 -3px var(--green)}
.nav-submenu-toggle{position:absolute;right:-18px;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:16px;height:28px;padding:0;border:0;background:transparent;color:var(--green)}
.nav-submenu-toggle span,.nav-mobile-trigger span{width:6px;height:6px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg);transition:transform .15s}
.nav-submenu-toggle[aria-expanded=true] span,.nav-mobile-trigger[aria-expanded=true] span{transform:rotate(225deg)}
.nav-mobile-trigger{display:none}
#main-nav .nav-dropdown{position:absolute;top:100%;left:0;z-index:101;width:max-content;min-width:190px;max-width:calc(100vw - 32px);padding:10px;background:#fff;border:1px solid var(--line);border-radius:0 0 8px 8px;box-shadow:0 10px 24px #123e251a}
#main-nav .nav-dropdown a{display:block;padding:11px 16px;white-space:nowrap;border-radius:4px;font-weight:500;color:var(--ink);line-height:1.65}
#main-nav .nav-dropdown a:hover,#main-nav .nav-dropdown a:focus-visible,#main-nav .nav-dropdown a.active{background:var(--soft);color:var(--green)}
#main-nav .nav-dropdown a.active{font-weight:700}
@media(min-width:1024px){#main-nav{height:100%}}
@media(max-width:1023px){
 #main-nav{max-height:calc(100dvh - 68px)}
 #main-nav .nav-item{display:block;align-self:auto;min-width:0}
 #main-nav .nav-parent,.nav-submenu-toggle{display:none}
 #main-nav .nav-mobile-trigger{display:flex;align-items:center;justify-content:space-between;width:100%;padding:14px 0;border:0;background:transparent;font:inherit;color:inherit;text-align:left}
 #main-nav .nav-mobile-trigger.active{color:var(--green);box-shadow:none}
 #main-nav .nav-dropdown{position:static;width:100%;min-width:0;max-width:100%;padding:4px 8px 10px;background:var(--soft);border:0;border-radius:5px;box-shadow:none}
 #main-nav .nav-dropdown a{white-space:normal;overflow-wrap:anywhere;padding:11px 12px}
}
@media(prefers-reduced-motion:reduce){.nav-submenu-toggle span,.nav-mobile-trigger span{transition:none}}

