/* Shared hero-to-content spacing. Kicker/TOC inset is included in the title gap. */
:root{--subpage-start:84px;--subpage-kicker-space:37px;--subpage-toc-inset:29px}
#main>.article-wrap{padding-top:var(--subpage-start)}
#main>.article-wrap:has(>.visual-section:first-of-type>.section-kicker){padding-top:calc(var(--subpage-start) - var(--subpage-kicker-space))}
#main>.article-wrap>.article-section:first-of-type{padding-top:0;margin-top:0}
#main>.article-wrap>.actions:empty{display:none}
#main>.article-wrap:has(>.individual-article){padding-top:calc(var(--subpage-start) - var(--subpage-toc-inset))}
#main>.article-wrap>.individual-article{padding-top:0}
#main>.sub-hero+.section,#main>.sub-hero+.contact-layout,#main .ddHero+.ddSplit{padding-top:var(--subpage-start)}
#main>.sub-hero+.section>.container>.filter-bar:first-child{margin-top:0}
@media(max-width:700px){:root{--subpage-start:56px;--subpage-kicker-space:31.25px;--subpage-toc-inset:23px}}

/* R&D overview only: one white surface, with balanced section spacing. */
#main>.article-wrap:has(>#R02:first-of-type){padding-top:0}
#main>.article-wrap>#R02{background:#fff;box-shadow:none;clip-path:none;margin-block:0;padding-block:var(--subpage-start)}

/* Approved artwork in equal frames; original files are preserved separately. */
.company-focus .company-focus-image{display:flex;align-items:center;justify-content:center;width:100%;aspect-ratio:5/3;margin-bottom:20px;background:#edf2e9}
.company-focus .company-focus-image img{display:block;object-fit:contain;object-position:center;width:100%;height:auto;max-height:100%;border:0;box-shadow:none;filter:none}
@media(max-width:700px){.company-focus .company-focus-image{max-height:210px}}

/* Trimmed transparent canvas, with 7% safe padding on each side. */
.company-focus .company-focus-image .focus-culture{max-width:51.5%}
.company-focus .company-focus-image .focus-research{max-width:41.83%}
.company-focus .company-focus-image .focus-partnership{max-width:min(93.98%,calc((100% - 48px)*1.14))}

/* Replacement art keeps the original floated icon footprint and text positions. */
#C05 .vision-art{display:block;position:relative;float:right;width:60px;height:60px;margin:0 0 24px 20px}
#C05 .vision-art img{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:58.8px;height:58.8px;max-width:none;object-fit:contain;border:0;box-shadow:none;filter:none;background:transparent}
@media(max-width:700px){#C05 .vision-art{width:45px;height:45px}#C05 .vision-art img{width:43.12px;height:43.12px}}

/* Only sustainability section icons; preserve the existing 55px footprint. */
:is(#CS02,#CS03,#CS04,#CS05) .sustainability-icon{display:flex;align-items:center;justify-content:center;width:55px;height:55px;margin-bottom:24px}
.sustainability-icon img{display:block;width:100%;height:100%;object-fit:contain;background:transparent;border:0;filter:none;box-shadow:none}
#CS03 .sustainability-icon img{max-width:96%;max-height:96%}
#CS05 .sustainability-icon img{max-width:97%;max-height:97%}

/* Homepage research artwork, retaining the existing card footprint. */
#H04 .home-research-icon{display:flex;align-items:center;justify-content:center;width:50px;height:50px;margin-bottom:20px}
#H04 .home-research-icon img{display:block;width:100%;height:100%;object-fit:contain;background:transparent;border:0;box-shadow:none;filter:none}
