patent-gallery.css:
.patent-gallery{background:#f6f8f5;border-top:1px solid var(--line)}
.certificate-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:36px}
.certificate-card{background:#fff;border:1px solid var(--line);min-width:0;display:flex}
.certificate-open{display:flex;flex-direction:column;width:100%;padding:24px;border:0;background:transparent;color:var(--ink);text-align:left;font:inherit;cursor:pointer}
.certificate-thumbnail{display:block;width:100%;height:300px;background:#fafbf9;margin-bottom:22px}
.certificate-thumbnail img{display:block;width:100%;height:100%;object-fit:contain}
.certificate-country{font-size:13px;color:var(--green);margin-bottom:6px}
.certificate-number{font-size:20px;margin-bottom:12px}
.certificate-title{font-size:15px;line-height:1.65;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:75px;margin-bottom:16px}
.certificate-action{display:flex;align-items:center;justify-content:space-between;min-height:44px;border-top:1px solid var(--line);width:100%;margin-top:auto;padding-top:12px;font-weight:600;color:var(--green)}
.certificate-open:hover{background:#f7faf7}.certificate-open:focus-visible,.certificate-dialog button:focus-visible,.certificate-dialog a:focus-visible,.certificate-viewer:focus-visible{outline:3px solid #a47c36;outline-offset:3px}
.certificate-dialog{width:min(1000px,calc(100% - 48px));max-width:none;max-height:90dvh;padding:0;border:0;color:var(--ink);background:white}
.certificate-dialog::backdrop{background:rgba(4,20,14,.78)}
.certificate-dialog-inner{display:flex;flex-direction:column;max-height:90dvh}
.certificate-toolbar{display:flex;align-items:flex-start;gap:24px;justify-content:space-between;padding:22px 24px 12px}
.certificate-toolbar h2{font-size:19px;line-height:1.5;margin:0}.certificate-toolbar p{font-size:13px;margin:0 0 6px;color:var(--green)}
.certificate-dialog button,.certificate-tools a{min-height:44px;font:inherit;font-size:14px;padding:10px 14px;background:white;border:1px solid var(--line);color:var(--green);cursor:pointer}
.certificate-close{flex-shrink:0}.certificate-tools{display:flex;flex-wrap:wrap;gap:10px;padding:0 24px 16px}
.certificate-viewer{min-height:0;overflow:auto;overscroll-behavior:contain;padding:20px;background:#edf0eb}
.certificate-full{display:block;width:auto;height:auto;max-height:calc(90dvh - 210px);max-width:100%;object-fit:contain;margin:0 auto}
.certificate-viewer.is-zoomed .certificate-full{width:var(--certificate-width);max-width:none;max-height:none}
@media(max-width:1023px){.certificate-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){.certificate-grid{grid-template-columns:1fr}.certificate-thumbnail{height:320px}.certificate-dialog{width:calc(100% - 24px);max-height:94dvh}.certificate-dialog-inner{max-height:94dvh}.certificate-toolbar{padding:16px;gap:12px}.certificate-toolbar h2{font-size:16px}.certificate-tools{padding:0 16px 12px}.certificate-viewer{padding:10px}}
